def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    # Endgame: grab last payoff with a defection only when it is safe enough.
    if n >= 99:
        return 'D'
    if n >= 96:
        recent_opp_c = opp[-8:].count('C')
        if recent_opp_c >= 6:
            return 'D'
        return 'C'

    # Track opponent behavior globally and recently.
    opp_d = opp.count('D')
    total = n
    look = 12 if n >= 12 else n
    recent = opp[-look:]
    recent_d = recent.count('D')
    recent_c = look - recent_d

    # Perfect cooperation: continue cooperating, with very rare probing late.
    if opp_d == 0:
        if n >= 80 and n % 11 == 0:
            return 'D'
        return 'C'

    # Perfect defection: defect, but occasionally test for a change.
    if opp_d == n:
        if n >= 4 and n % 13 == 0:
            return 'C'
        return 'D'

    # Immediate retaliation: if opponent just defected, mostly defect.
    last_opp = opp[-1]
    last_me = me[-1]

    if last_opp == 'D':
        if recent_d >= 4:
            return 'D'
        # If opponent has mostly cooperated but just defected, forgive sometimes.
        if opp_d * 4 <= n and rng.random() < 0.35:
            return 'C'
        if last_me == 'D' and recent_d <= 2 and rng.random() < 0.5:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    # If we just defected and they cooperated, occasionally continue exploiting.
    if last_me == 'D' and last_opp == 'C':
        if n >= 20 and recent_c * 4 >= look * 3 and rng.random() < 0.25:
            return 'D'
        return 'C'

    # Heavy recent defection: punish strongly.
    if recent_d * 3 >= look:
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # Moderate recent defection: tit-for-tat with forgiveness.
    if recent_d * 2 >= look:
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # Low recent defection: cooperate, with occasional safe probing.
    if n >= 15 and recent_d == 0 and opp_d * 5 <= n:
        if n % 17 == 0:
            return 'D'
        return 'C'

    # Detect alternating / periodic patterns: if opponent defects at a regular cadence,
    # match their expected next move.
    if n >= 6:
        period = 0
        for p in (2, 3, 4, 5):
            if n < 2 * p:
                continue
            match = True
            for i in range(n - 1, n - 1 - p, -1):
                if i - p < 0:
                    match = False
                    break
                if opp[i] != opp[i - p]:
                    match = False
                    break
            if match:
                period = p
                break
        if period:
            expected = opp[n - period]
            if expected == 'D':
                return 'D'
            return 'C'

    # Default: cooperate to maintain mutual cooperation.
    return 'C'
